package main

import (
	"context"
	"testing"

	"google.golang.org/protobuf/types/known/structpb"

	metadatav1 "github.com/mellifera/mellifera/proto/mellifera/metadata/v1"
	scannerv1 "github.com/mellifera/mellifera/proto/mellifera/scanner/v1"
)

// matchReq builds a MatchRequest from fixture structs: the item's parsed
// document plus the core-surfaced doc.identifiers (existing_ids). No I/O —
// the whole dispatch is a pure function of these two structs.
func matchReq(t *testing.T, parsed, existing map[string]any) *metadatav1.MatchRequest {
	t.Helper()
	req := &metadatav1.MatchRequest{}
	if parsed != nil {
		p, err := structpb.NewStruct(parsed)
		if err != nil {
			t.Fatalf("fixture parsed struct: %v", err)
		}
		req.Item = &scannerv1.IdentifyResult{Parsed: p}
	}
	if existing != nil {
		e, err := structpb.NewStruct(existing)
		if err != nil {
			t.Fatalf("fixture existing_ids struct: %v", err)
		}
		req.ExistingIds = e
	}
	return req
}

// TestMatch drives the document-shape dispatch (box 1.1): the four shapes plus
// the degenerate no-title document, all with fixture structs and no I/O.
func TestMatch(t *testing.T) {
	p := &sourceImpl{}
	tests := []struct {
		name     string
		parsed   map[string]any
		existing map[string]any
		applies  bool
		query    map[string]any
		reason   string
	}{
		{
			// Serial-record doc: display title + season, no episode key →
			// anime-search shape.
			name:    "serial-record doc applies with anime-search query",
			parsed:  map[string]any{"serial_record": true, "title": "Ковбой Бибоп", "season": int64(1)},
			applies: true,
			query:   map[string]any{"title": "Ковбой Бибоп", "season": float64(1)},
			reason:  "serial-record anime search",
		},
		{
			// REAL serial-record shape: the scanner stamps NO title — the
			// search title derives from dir_name_raw (the shared grammar's
			// season cut), the season from the Sxx marker.
			name: "serial-record doc derives title+season from dir_name_raw",
			parsed: map[string]any{
				"serial_record": true, "dir_name_raw": "Frieren S02", "backing": "directory",
				"series_relative_path": "Frieren S02", "series_sidecars": []any{},
			},
			applies: true,
			query:   map[string]any{"title": "Frieren", "season": float64(2)},
			reason:  "serial-record anime search",
		},
		{
			// A stamped season key wins over the derived marker's value; the
			// title still derives from the raw directory facts.
			name: "serial-record doc keeps a stamped season over the derived one",
			parsed: map[string]any{
				"serial_record": true, "title": "", "season": int64(3), "dir_name_raw": "Frieren S02",
			},
			applies: true,
			query:   map[string]any{"title": "Frieren", "season": float64(3)},
			reason:  "serial-record anime search",
		},
		{
			// A serial record with NO directory facts and NO title is a
			// skipped stage, not an error.
			name:    "serial-record doc without directory facts does not apply",
			parsed:  map[string]any{"serial_record": true, "backing": "directory"},
			applies: false,
			reason:  "serial record without directory facts",
		},
		{
			// Film-parsed doc: title, no season/episode keys → movie-kind
			// search shape.
			name:    "film-parsed doc applies via movie-kind search",
			parsed:  map[string]any{"title": "Perfect Blue", "year": int64(1997)},
			applies: true,
			query:   map[string]any{"title": "Perfect Blue", "kind": "movie"},
			reason:  "film document movie search",
		},
		{
			// Episode doc: season + episode keys → never applies.
			name:    "episode doc does not apply",
			parsed:  map[string]any{"title": "Show", "season": int64(1), "episode": int64(5)},
			applies: false,
			reason:  "episode document: episode files carry no shikimori namespace",
		},
		{
			// ID anchor wins over ANY document shape — even an episode doc.
			name:     "anchored re-match by shikimori_id wins over shape",
			parsed:   map[string]any{"title": "Show", "season": int64(1), "episode": int64(5)},
			existing: map[string]any{"shikimori_id": int64(123)},
			applies:  true,
			query:    map[string]any{"shikimori_id": float64(123)},
			reason:   "matched by shikimori_id 123",
		},
		{
			name:    "document without a display title does not apply",
			parsed:  map[string]any{"season": int64(1)},
			applies: false,
			reason:  "no display title in document",
		},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			res, err := p.Match(context.Background(), matchReq(t, tc.parsed, tc.existing))
			if err != nil {
				t.Fatalf("Match: %v", err)
			}
			if res.GetApplies() != tc.applies {
				t.Fatalf("applies = %v, want %v (reason=%q)", res.GetApplies(), tc.applies, res.GetReason())
			}
			if res.GetReason() != tc.reason {
				t.Errorf("reason = %q, want %q", res.GetReason(), tc.reason)
			}
			if !tc.applies {
				return
			}
			got := res.GetQuery().AsMap()
			if len(got) != len(tc.query) {
				t.Fatalf("query = %v, want %v", got, tc.query)
			}
			for k, want := range tc.query {
				if got[k] != want {
					t.Errorf("query[%q] = %v, want %v", k, got[k], want)
				}
			}
		})
	}
}

// TestMatchAnchoredClaimsID pins the anchored MatchResult's resolved_ids claim:
// the proto channel for the id the plugin already knows (box 1.1: "id-anchored
// re-match").
func TestMatchAnchoredClaimsID(t *testing.T) {
	p := &sourceImpl{}
	res, err := p.Match(context.Background(), matchReq(t,
		map[string]any{"title": "Ковбой Бибоп", "season": int64(1)},
		map[string]any{"shikimori_id": int64(123)}))
	if err != nil {
		t.Fatalf("Match: %v", err)
	}
	ids := res.GetResolvedIds().AsMap()
	if ids["shikimori_id"] != float64(123) {
		t.Fatalf("resolved_ids = %v, want {shikimori_id: 123}", ids)
	}
	if got := res.GetConfidence(); got != 1.0 {
		t.Errorf("confidence = %v, want 1.0 for an id-anchored match", got)
	}
}
